where.if:
AND EXISTS (
    SELECT 1 FROM meal_activity_member m
    WHERE m.activity_id = meal_activity.id
      AND m.user_id = #{joinedUserId}
      AND m.status = 1
)

mapper.insert:
INSERT INTO meal_activity (
    creator_id, title, meet_time, meet_place, food_type,
    related_food_id, related_merchant_id, max_members, current_members,
    description, signup_deadline, status
) VALUES (
    #{creatorId}, #{title}, #{meetTime}, #{meetPlace}, #{foodType},
    #{relatedFoodId}, #{relatedMerchantId}, #{maxMembers}, #{currentMembers},
    #{description}, #{signupDeadline}, #{status}
)

mapper.select:
SELECT
FROM meal_activity
ORDER BY created_at DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE meal_activity
SET status = #{status}
WHERE id = #{id}
